CREATE OR REPLACE FUNCTION public.icash_claim_automatic_export_capacity(p_release text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e icash_research_private.owner_exports;r icash_research_private.owner_export_capacity_reviews;previous icash_research_private.owner_export_capacity_reviews;request uuid:=gen_random_uuid();source_policy text;
begin
 if p_release is null or p_release !~ '^[a-f0-9]{40}$' or not exists(select 1 from icash_research_private.export_capacity_automation where id=1 and enabled)
  or not public.icash_owner_active_export_enabled() or not public.icash_dealmachine_capacity_available(3)
  or not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return null;end if;
 select * into e from icash_research_private.owner_exports where terminal_at is null and capacity_review_id is null for update;
 if not found or icash_research_private.capacity_source_current(e.id,md5(e.receipt::text)) is distinct from true then return null;end if;
 source_policy:=icash_research_private.capacity_source_policy(e.id,md5(e.receipt::text));
 select * into previous from icash_research_private.owner_export_capacity_reviews where export_id=e.id order by created_at desc,id desc limit 1;
 if found then
  -- Explicit manual reviews retain their existing operator authority.
  if previous.auto_policy is distinct from source_policy or previous.receipt_hash<>md5(e.receipt::text) or previous.state not in ('checking','held')
   or coalesce(previous.started_at,previous.created_at)+make_interval(secs=>least(3600,120*power(2,least(previous.auto_attempt-1,5))::integer))>now() then return null;end if;
 end if;
 insert into icash_research_private.owner_export_capacity_reviews(export_id,receipt_hash,reviewed_release,auto_policy,auto_attempt,supersedes)
 values(e.id,md5(e.receipt::text),p_release,source_policy,coalesce(previous.auto_attempt,0)+1,previous.id) returning * into r;
 if not public.icash_take_dealmachine_request('owner_preview',null,'export-capacity-auto:'||r.id||':inventory',request) then
  update icash_research_private.owner_export_capacity_reviews set state='held' where id=r.id;return null;
 end if;
 update icash_research_private.owner_export_capacity_reviews set state='checking',request_id=request,started_at=clock_timestamp() where id=r.id;
 insert into icash_research_private.export_capacity_probes(review_id,probe,request_id) values(r.id,'inventory',request);
 return jsonb_build_object('reviewId',r.id,'requestId',request);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_export_capacity_review()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r icash_research_private.owner_export_capacity_reviews;e icash_research_private.owner_exports;new_request uuid:=gen_random_uuid();
begin
 if not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return null;end if;
 select * into r from icash_research_private.owner_export_capacity_reviews where state='planned' order by created_at,id limit 1 for update skip locked;
 if not found or not public.icash_dealmachine_capacity_available(1) then return null;end if;
 select * into e from icash_research_private.owner_exports where id=r.export_id for update;
 if not found or e.terminal_at is not null or e.completed_at is not null or e.capacity_review_id is not null
  or md5(e.receipt::text) is distinct from r.receipt_hash or e.receipt->'httpStatus' is distinct from '500'::jsonb
  or e.receipt#>>'{raw,error,code}' is distinct from 'internal_error'
  or coalesce(e.receipt#>>'{raw,error,request_id}','') !~ '^req_[A-Za-z0-9_-]{1,100}$'
  or (e.receipt->'raw') ? 'export_id'
  or not exists(select 1 from icash_research_private.requests q where q.id=e.id and q.admitted and q.finished_at is not null and q.result->>'outcome'='http_error' and q.result->'httpStatus'='500'::jsonb)
  or exists(select 1 from icash_research_private.owner_exports x where x.id<>e.id and x.terminal_at is null and x.capacity_review_id is null)
  then update icash_research_private.owner_export_capacity_reviews set state='held' where id=r.id;return null;end if;
 if not public.icash_take_dealmachine_request('owner_preview',null,'export-capacity-review:'||r.id,new_request) then return null;end if;
 update icash_research_private.owner_export_capacity_reviews set state='checking',request_id=new_request,started_at=clock_timestamp() where id=r.id;
 return jsonb_build_object('reviewId',r.id,'requestId',new_request);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_owner_preflight_cleanup(p_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p icash_research_private.owner_export_preflights;
begin
 if not public.icash_dealmachine_capacity_available(1) then return null;end if;
 select * into p from icash_research_private.owner_export_preflights where (p_id is null or id=p_id) and list_id is not null and deleted_at is null and cleanup_attempts<3
  and (cleanup_until is null or cleanup_until<clock_timestamp()) and (state in ('empty','ready','held') or
 case when state='waiting' and cleanup_attempts=0 and (icash_research_private.owner_preflight_list_known(id)) then created_at<=clock_timestamp()-interval '30 minutes'
 else started_at<clock_timestamp()-interval '5 minutes' end)
  order by created_at,id limit 1 for update skip locked;
 if not found then return null;end if;
 update icash_research_private.owner_export_preflights set cleanup_token=gen_random_uuid(),cleanup_until=clock_timestamp()+interval '5 minutes',cleanup_attempts=cleanup_attempts+1 where id=p.id returning * into p;
 return jsonb_build_object('id',p.id,'token',p.cleanup_token,'listId',p.list_id);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_owner_preflight(p_account uuid, p_items jsonb, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare quota_result jsonb;p icash_research_private.owner_export_preflights;item jsonb;ids jsonb;finger text;new_id uuid:=gen_random_uuid();parent_id uuid;next_generation integer:=1;cached boolean;renew boolean:=false;
begin
 if not exists(select 1 from icash_research_private.owner_export_settings where id=1 and preflight_enabled) then return '{"status":"disabled"}';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 5
  or octet_length(p_items::text)>524288 or jsonb_typeof(p_request->'people_ids') is distinct from 'array' then return '{"status":"held"}';end if;
 select jsonb_agg(to_jsonb(id) order by position) into ids from(
  select v#>>'{}' id,min(i.ordinality*1000+x.ordinality) position from jsonb_array_elements(p_items) with ordinality i(item,ordinality),jsonb_array_elements(i.item->'ids') with ordinality x(v,ordinality) group by v
 ) q;
 if ids is distinct from p_request->'people_ids' or jsonb_array_length(ids) not between 1 and 125
  or exists(select 1 from jsonb_array_elements_text(ids) id where id !~ '^per_[1-9][0-9]{0,15}$' or substring(id from 5)::numeric>9007199254740991)
  or (p_request @> '{"property_match":"owner","anchor":"person","require_phone":true,"scrub_dnc":true,"active_phones_only":true}') is distinct from true then return '{"status":"held"}';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('owner-preflight:'||p_account,0)) then return '{"status":"pending"}';end if;
 if not exists(select 1 from public.icash_accounts where id=p_account and not bot_paused)
  or not public.icash_membership_work_allowed(p_account) or not public.icash_owner_export_people_available(ids) then return '{"status":"held"}';end if;
 for item in select value from jsonb_array_elements(p_items) loop
  if not exists(select 1 from public.icash_screening_jobs s where s.id=(item->>'screeningId')::uuid and s.account_id=p_account and s.state='complete' and s.snapshot=item->'snapshot')
   or not public.icash_owner_enrichment_unstarted(p_account,(item->>'screeningId')::uuid,'owners:'||p_account||':'||(item->>'screeningId')) then return '{"status":"held"}';end if;
 end loop;
 finger:=md5(jsonb_build_array(p_items,p_request)::text);
 if exists(select 1 from icash_research_private.owner_export_settings where id=1 and enabled and preflight_enabled and preflight_quota_recovery_enabled)
  and exists(select 1 from icash_research_private.owner_export_preflights retry_preflight
   join icash_research_private.owner_preflight_quota_deferrals denial on denial.preflight_id=retry_preflight.id and denial.lease=retry_preflight.lease
   where retry_preflight.account_id=p_account and retry_preflight.fingerprint=finger) then
  perform 1 from public.icash_operating_budget where id=1 and enabled for update;
  if not found then return '{"status":"held"}';end if;
  perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
  if not found then return '{"status":"held"}';end if;
 end if;

 select * into p from icash_research_private.owner_export_preflights where account_id=p_account and fingerprint=finger order by generation desc limit 1 for update;
 cached:=found;
 if cached and icash_research_private.owner_preflight_renewable(p.id) then parent_id:=p.id;next_generation:=p.generation+1;renew:=true;end if;
 if cached and not renew then
  if p.items is distinct from p_items or p.request is distinct from p_request then return '{"status":"held"}';end if;
  quota_result:=icash_research_private.owner_preflight_quota_resume(p.id,p_items,p_request);
  if quota_result is not null then return quota_result;end if;
  if p.state in ('ready','empty') then return jsonb_build_object('status',case when p.checked_at>clock_timestamp()-interval '30 minutes' or p.state='empty' then p.state else 'held' end);end if;
  if p.state='held' or p.created_at<clock_timestamp()-interval '30 minutes' or (p.state='waiting' and p.cleanup_attempts>0) then return '{"status":"held"}';end if;
  if p.state<>'waiting' or p.next_check_at>clock_timestamp() or not public.icash_dealmachine_capacity_available(3) then
   return jsonb_build_object('status',case when p.state in ('creating','checking') and p.started_at<clock_timestamp()-interval '90 seconds' then 'held' else 'pending' end);
  end if;
  if p.indexing_next_step is not null and (p.indexing_checks>=6 or not exists(
   select 1 from icash_research_private.owner_export_settings where id=1 and preflight_indexing_enabled)) then return '{"status":"held"}';end if;
  update icash_research_private.owner_export_preflights set indexing_checks=indexing_checks+case when indexing_next_step is null then 0 else 1 end,state='checking',lease=gen_random_uuid(),started_at=clock_timestamp() where id=p.id returning * into p;
 else
  perform 1 from public.icash_operating_budget where id=1 for update;
  if not found then return '{"status":"held"}';end if;
  if renew then
   -- Pause and source changes that won the shared budget lock also win renewal.
   perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
   if not found or not public.icash_membership_work_allowed(p_account) or not public.icash_owner_export_people_available(ids)
    or p.items is distinct from p_items or p.request is distinct from p_request
    or not exists(select 1 from public.icash_discovery_configs c join public.icash_operation_rates r on r.id=c.contact_rate_id
     where c.account_id=p_account and c.enabled and c.contacts_enabled and c.data_rights_until>now()
      and r.enabled and r.operation='owner_enrichment' and r.expires_at>now())
    or not exists(select 1 from public.icash_wallets where account_id=p_account and balance_cents>reserved_cents)
    then return '{"status":"held"}';end if;
   for item in select value from jsonb_array_elements(p_items) loop
    if not exists(select 1 from public.icash_screening_jobs s where s.id=(item->>'screeningId')::uuid and s.account_id=p_account
      and s.state='complete' and s.snapshot=item->'snapshot' and s.completed_at between now()-interval '24 hours' and now()
      and s.result->'financialCheck'->>'status'='eligible' and not s.snapshot ? 'sellerRequest'
      and s.snapshot->>'propertyType'='house' and public.icash_research_state_allowed(s.snapshot->'raw'->'data'->>'state'))
     or not public.icash_owner_enrichment_unstarted(p_account,(item->>'screeningId')::uuid,'owners:'||p_account||':'||(item->>'screeningId'))
     or coalesce(p_request->'mobile_only','false'::jsonb) is distinct from to_jsonb(public.icash_owner_targeting_pool(p_account,(item->>'screeningId')::uuid)='mobile')
     or exists(select 1 from public.icash_property_controls where account_id=p_account and property_id=item->'snapshot'->>'propertyId' and manual)
     then return '{"status":"held"}';end if;
   end loop;
  end if;

  if exists(select 1 from jsonb_array_elements(p_items) i where i->>'screeningId'<>p_items->0->>'screeningId' and exists(select 1 from public.icash_automation_tickets t where t.screening_id=(i->>'screeningId')::uuid)) then return '{"status":"quota_wait"}';end if;
  if exists(select 1 from jsonb_array_elements(p_items) i where public.icash_owner_preflight_sibling_waiting(p_account,(i->>'screeningId')::uuid,i->'snapshot',(p_items->0->>'screeningId')::uuid)) then return '{"status":"quota_wait"}';end if;
  if icash_research_private.owner_preflight_cohort(p_account,(p_items->0->>'screeningId')::uuid) is not null and icash_research_private.owner_preflight_cohort(p_account,(p_items->0->>'screeningId')::uuid) is distinct from p_items then return '{"status":"pending"}';end if;
  if not public.icash_dealmachine_capacity_available(1) then return '{"status":"quota_wait"}';end if;
  insert into icash_research_private.owner_export_preflights(id,account_id,fingerprint,items,request,state,list_name,supersedes,generation)
   values(new_id,p_account,finger,p_items,p_request,'creating','icash-owner-preflight-'||new_id,parent_id,next_generation) returning * into p;
  insert into icash_research_private.owner_export_preflight_items select p.id,p_account,(i->>'screeningId')::uuid,md5((i->'snapshot')::text) from jsonb_array_elements(p_items) i;
 end if;
 return jsonb_build_object('status',case when p.state='creating' then 'create' else 'check' end,'id',p.id,'lease',p.lease,'listId',p.list_id,'name',p.list_name,'ids',ids,'mobileOnly',p.request->'mobile_only'='true'::jsonb,'nextStep',p.indexing_next_step);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_research_exclusions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s icash_research_private.exclusions;ids text[];t uuid:=gen_random_uuid();action text;
begin
 if not exists(select 1 from icash_research_private.settings where id=1 and enabled and exclusions_enabled) or not public.icash_dealmachine_capacity_available(1) then return null;end if;
 if exists(select 1 from icash_research_private.settings where id=1 and pruned_at<now()-interval '1 day') then
  perform public.icash_prune_research_requests();update icash_research_private.settings set pruned_at=now() where id=1;
 end if;
 select * into s from icash_research_private.exclusions where id=1 for update skip locked;
 if not found or s.next_at>now() or s.lease_until>now() then return null;end if;
 if s.list_id is null then action:=case when s.state='new' then 'create' else 'recover' end;ids:='{}';
 else select coalesce(array_agg(property_id),'{}') into ids from (select property_id from (
  select property_id from icash_research_private.exclusion_items where synced_at is null
  union select property_id from icash_research_private.targeting_acquired_properties where synced_at is null and (
   exists(select 1 from icash_research_private.targeting_settings where id=1 and enabled)
   or exists(select 1 from public.icash_discovery_filter_pages where plan->>'version'='seller-targeting-v1' and state not in ('empty','unavailable')))
 ) pending order by property_id limit 1000) x;
  if cardinality(ids)=0 then return null;end if;action:='sync';
 end if;
 update icash_research_private.exclusions set token=t,lease_until=now()+interval '1 minute',next_at=now()+interval '10 seconds',batch=ids,state=case when action='create' then 'creating' else state end where id=1;
 return jsonb_build_object('action',action,'token',t,'name',s.name,'listId',s.list_id,'ids',ids);
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_acquisition()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;j uuid;t public.icash_automation_tickets;backlog integer;allowance bigint;minimum_quote bigint;
begin
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;
 if not found then return null;end if;
 perform public.icash_settle_pending_dealmachine();
 -- Expiry/exhaustion is terminal only for this exact proven-unstarted family.
 update public.icash_automation_tickets retry_ticket set outcome=case when owner_preview_deferrals>=8 then 'owner_preview_retry_exhausted' else 'owner_preview_expired' end
 where retry_ticket.kind='contacts' and retry_ticket.state='held' and retry_ticket.outcome='owner_preview_rate_limited'
 and (retry_ticket.owner_preview_deferrals>=8 or retry_ticket.owner_preview_retry_until<=clock_timestamp())
 and public.icash_owner_enrichment_unstarted(retry_ticket.account_id,retry_ticket.screening_id,'owners:'||retry_ticket.account_id||':'||retry_ticket.screening_id);
 update public.icash_automation_tickets set state='held',outcome='expired' where kind in ('contacts','discovery') and state='issued' and expires_at<=now();
 -- Leave other scheduler work available; billing and expiry checks above still run.
 if not public.icash_dealmachine_capacity_available() then return null;end if;
 for c in select d.* from public.icash_discovery_configs d join public.icash_accounts a on a.id=d.account_id join public.icash_wallets w on w.account_id=a.id
 where d.enabled and d.auto_enabled and d.next_run_at<=now() and d.data_rights_until>now() and not a.bot_paused and w.balance_cents>w.reserved_cents
 and not exists(select 1 from public.icash_automation_tickets x where x.account_id=a.id and ((x.state='issued' and x.expires_at>now()) or (x.state='consumed' and x.created_at>now()-interval '5 minutes')))
 order by
  -- Ordinary overdue accounts retain an aging escape from the due-list queue.
  case when d.next_run_at<now()-interval '10 minutes' then d.next_run_at end nulls last,
  case when d.contacts_enabled and d.contact_rate_id is not null
   and public.icash_owner_active_export_capacity() in ('disabled','ready')
   then public.icash_owner_preflight_due_at(d.account_id,null::uuid) end nulls last,
  case when d.contacts_enabled and d.contact_rate_id is not null
   and public.icash_owner_active_export_capacity() in ('disabled','ready')
   then public.icash_owner_retry_due_at(d.account_id) end nulls last,
  (d.next_run_at<now()-interval '5 minutes') desc,
  case when d.next_run_at<now()-interval '5 minutes' then d.next_run_at end,
  coalesce((public.icash_daily_work_target(d.account_id)->>'priorityRatio')::numeric,1),
  d.next_run_at,d.account_id limit 5 for update of d skip locked loop
 perform public.icash_prepare_research_efficiency(c.account_id);
 select * into c from public.icash_discovery_configs where account_id=c.account_id;
 perform public.icash_refresh_opportunity_outcomes(c.account_id);
 allowance:=public.icash_prospecting_available(c.account_id);
 select min(quote) into minimum_quote from (
  select public.icash_research_admission_quote(c.account_id,'property_search',r.charge_cents) quote
   from public.icash_operation_rates r where r.id=c.rate_id
  union all
  select public.icash_research_admission_quote(c.account_id,'owner_enrichment',r.charge_cents)
   from public.icash_operation_rates r where c.contacts_enabled and public.icash_owner_active_export_capacity() in ('disabled','ready') and r.id=c.contact_rate_id
 ) quotes;
 if minimum_quote is null or allowance<minimum_quote then
  update public.icash_discovery_configs set next_run_at=now()+interval '60 seconds' where account_id=c.account_id;
  continue;
 end if;
 j:=null;
 if c.contacts_enabled and c.contact_rate_id is not null then j:=public.icash_enrichment_candidate(c.account_id);end if;
 if j is not null then
 update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind,screening_id) values(c.account_id,'contacts',j)
 on conflict(screening_id) do update set token=gen_random_uuid()::text||gen_random_uuid()::text,state='issued',outcome=null,completed_at=null,created_at=now(),expires_at=least(now()+interval '2 minutes',coalesce(public.icash_automation_tickets.owner_preview_retry_until,now()+interval '2 minutes')),issue_attempts=case when public.icash_automation_tickets.outcome='owner_preview_rate_limited' then public.icash_automation_tickets.issue_attempts else public.icash_automation_tickets.issue_attempts+1 end
 returning * into t;
 return jsonb_build_object('token',t.token);
 end if;
 -- Provider capacity remains bounded while completed attempts free the queue.
 backlog:=public.icash_pending_opportunity_count(c.account_id);
 if c.exhausted or backlog>=c.max_open_prospects or not public.icash_outbound_search_due(c.account_id) then
  update public.icash_discovery_configs set next_run_at=now()+interval '60 seconds' where account_id=c.account_id;
  continue;
 end if;
 update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind) values(c.account_id,'discovery') returning * into t;
 return jsonb_build_object('token',t.token);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION icash_research_private.owner_preflight_quota_resume(p_id uuid, p_items jsonb, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p icash_research_private.owner_export_preflights;d icash_research_private.owner_preflight_quota_deferrals;item jsonb;
begin
 if not exists(select 1 from icash_research_private.owner_export_settings where id=1 and enabled and preflight_enabled and preflight_quota_recovery_enabled) then return null;end if;
 select * into p from icash_research_private.owner_export_preflights where id=p_id for update;
 select * into d from icash_research_private.owner_preflight_quota_deferrals where preflight_id=p.id and lease=p.lease;
 if not found then return null;end if;
 if p.items is distinct from p_items or p.request is distinct from p_request
  or p.started_at is distinct from d.started_at or md5(p.receipts::text) is distinct from d.receipts_hash
  or p.checked_at is not null or p.deleted_at is not null or p.cleanup_attempts<>0
  or p.state not in ('creating','checking') or p.created_at>clock_timestamp()
  or p.created_at<=clock_timestamp()-(case when d.step='create' then interval '5 minutes' else interval '30 minutes' end)
  or (d.step='eligible' and p.started_at<=clock_timestamp()-interval '90 seconds')
  or exists(select 1 from icash_research_private.requests r where r.admitted
   and r.operation_key='owner-preflight:'||p.id||':'||d.step and r.created_at>=d.started_at)
  then return '{"status":"held"}';end if;
 -- Match the ordinary ticket's first 30-second backoff; its existing exponential
 -- retry limit remains authoritative. This does not reserve provider requests.
 if d.created_at>clock_timestamp()-interval '30 seconds' or not public.icash_dealmachine_capacity_available(case when d.step='baseline' then 3 else 1 end)
  then return '{"status":"pending"}';end if;
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;
 if not found then return '{"status":"held"}';end if;
 perform 1 from public.icash_accounts where id=p.account_id and not bot_paused for update;
 if not found or public.icash_membership_work_allowed(p.account_id) is distinct from true or public.icash_owner_export_people_available(p.request->'people_ids') is distinct from true
  then return '{"status":"held"}';end if;
 for item in select value from jsonb_array_elements(p.items) loop
  if public.icash_owner_enrichment_retry_current(p.account_id,(item->>'screeningId')::uuid) is distinct from true
   or not exists(select 1 from public.icash_screening_jobs s where s.id=(item->>'screeningId')::uuid
    and s.account_id=p.account_id and s.snapshot=item->'snapshot')
   or coalesce(p.request->'mobile_only','false'::jsonb) is distinct from to_jsonb(public.icash_owner_targeting_pool(p.account_id,(item->>'screeningId')::uuid)='mobile')
   then return '{"status":"held"}';end if;
 end loop;
 -- An eligible count retains its original baseline handler's 90-second window.
 update icash_research_private.owner_export_preflights set lease=gen_random_uuid(),
  started_at=case when d.step='eligible' then started_at else clock_timestamp() end
 where id=p.id returning * into p;
 return jsonb_build_object('status',case when d.step='create' then 'create' else 'check' end,
  'id',p.id,'lease',p.lease,'listId',p.list_id,'name',p.list_name,'ids',p.request->'people_ids',
  'mobileOnly',p.request->'mobile_only'='true'::jsonb,'nextStep',d.step);
end $function$
